-- Kit Management System\n-- Allows admins to create, edit, and save kits with items and armor\n\nlocal Kits = {}\n\n-- Create a new kit\nfunction Kits.createKit(name)\n    Kits[name] = { items = {}, armor = {} }\n    print("Kit '\"..name.."\"' created.")\nend\n\n-- Add item to a kit\nfunction Kits.addItemToKit(kitName, item)\n    if Kits[kitName] then\n        table.insert(Kits[kitName].items, item)\n        print("Item '\"..item.."\"' added to kit '\"..kitName.."\"'.")\n    else\n        print("Kit '\"..kitName.."\"' does not exist.")\n    end\nend\n\n-- Add armor to a kit\nfunction Kits.addArmorToKit(kitName, armor)\n    if Kits[kitName] then\n        table.insert(Kits[kitName].armor, armor)\n        print("Armor '\"..armor.."\"' added to kit '\"..kitName.."\"'.")\n    else\n        print("Kit '\"..kitName.."\"' does not exist.")\n    end\nend\n\n-- Save the kits (for demonstration purposes, we'll just print them)\nfunction Kits.saveKits()\n    print("Kits saved:")\n    for name, kit in pairs(Kits) do\n        print("Kit Name: ", name)\n        print("Items:", table.concat(kit.items, ", "))\n        print("Armor:", table.concat(kit.armor, ", "))\n    end\nend\n\n-- Example usage (to be removed in production)\n-- Kits.createKit("Warrior")\n-- Kits.addItemToKit("Warrior", "Sword")\n-- Kits.addArmorToKit("Warrior", "Shield")\n-- Kits.saveKits()\n\nreturn Kits